type Stage = 'edit' | 'planned' | 'stills' | 'choose' | 'rendering' | 'delivered' | 'failed'
type Still = { id: string; url: string; score?: number; reasons?: string[] }
type Note = { message?: string; code?: string }
type Form = { foto: string; frase: string; oferta: string; beneficios: string; cta: string; language: string; formato: CenaEscolhaFormat; voice_mode: 'narrated' | 'talking'; rota: '' | 'kling3' | 'kling4' | 'seedance2' | 'veo31'; presenter_id: string; category: '' | CenaCategory; scenario_id: string }
type Saved = { version: typeof CENA_ESCOLHA_MARK; form: Form; order_id: string; stage: Stage; stills: Still[]; still_id: string; narration_used: string; quality_notes: Note[]; credits: number | null; photo_round?: number; max_photo_rounds?: number; photo_failure?: boolean; choice_locked?: boolean; sample?: boolean }
const COMPLETE_CREDITS = adsV2Credits('commercial', 15)
const SAMPLE_PLANS: readonly { tier: CheckoutPlanTier; name: string }[] = [{ tier: 'starter', name: 'Starter' }, { tier: 'basic', name: 'Creator' }, { tier: 'pro', name: 'Studio' }, { tier: 'business', name: 'Business' }]
const https = (v: unknown): v is string => { try { return typeof v === 'string' && new URL(v).protocol === 'https:' } catch { return false } }
const uuid = (v: unknown): v is string => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(v)
const savedStages: readonly Stage[] = ['planned', 'stills', 'choose', 'rendering', 'delivered', 'failed']
function validForm(value: unknown): value is Form {
  if (!value || typeof value !== 'object') return false
  const f = value as Record<string, unknown>
  return ['foto', 'frase', 'oferta', 'beneficios', 'cta', 'language', 'presenter_id', 'category', 'scenario_id'].every(k => typeof f[k] === 'string') && escolhaFormat(f.formato) && ['narrated', 'talking'].includes(String(f.voice_mode)) && ['', 'kling3', 'kling4', 'seedance2', 'veo31'].includes(String(f.rota))
}
