    if (code === 'cena_photo_credits_required') return t(`Para preparar as fotos grátis, tenha ${renderCredits} créditos de saldo ou um plano com Studio Ads. Os créditos só são usados ao gerar o vídeo.`, `To prepare free stills, keep ${renderCredits} credits in your balance or use a plan with Studio Ads. Credits are only used when you generate the video.`)
