      if (!r.ok) { if (action === 'render') absorb(data); if (action === 'upgrade' && r.status === 402) { setShowPlans(true); if (typeof data.balance === 'number') setPurchaseBalance(data.balance) } throw new StepError(failureMessage(data), r.status) }
